CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, code TEXT NOT NULL, name TEXT NOT NULL, location TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT 'PULSE');
CREATE TABLE IF NOT EXISTS pm_plans (id TEXT PRIMARY KEY, code TEXT NOT NULL, title TEXT NOT NULL, asset_code TEXT NOT NULL, frequency TEXT NOT NULL DEFAULT '', next_due TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS migration_keys (source TEXT NOT NULL, kind TEXT NOT NULL, external_id TEXT NOT NULL, record_id TEXT NOT NULL, imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(source,kind,external_id));
